// Static sitemap for the design-reference build. On Wix, the sitemap is generated by Wix.
const BASE_URL = process.env.SITE_URL || 'https://www.kotyark.com';

const PATHS = [
  ['', 1.0], ['/about', 0.8], ['/products', 0.9], ['/products/biodiesel', 0.8], ['/products/crude-glycerin', 0.8],
  ['/contact', 0.7], ['/investors', 0.9], ['/investors/sebi-lodr', 0.7], ['/investors/closing-trading-window', 0.6],
  ['/investors/misc-sebi-disclosure', 0.6], ['/investors/board-meetings', 0.6], ['/investors/audited-financial-statements', 0.6],
  ['/investors/annual-general-meeting', 0.6], ['/investors/extra-ordinary-general-meetings', 0.6], ['/investors/company-policies', 0.6],
  ['/investors/merger-and-amalgamation', 0.6], ['/investors/migration-to-main-board', 0.6], ['/investors/smart-odr', 0.6],
  ['/investors/unpaid-dividend', 0.6], ['/investors/postal-ballot', 0.6], ['/investors/integrated-filling', 0.6], ['/investors/moa-aoa', 0.6],
];

export default function sitemap() {
  return PATHS.map(([p, priority]) => ({ url: `${BASE_URL}${p}`, lastModified: new Date(), priority }));
}
